fn read_idx(path: &str) -> Result<Vec<Rec>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 9 || &raw[0..5] != b"SILT1" { return Err(1); }
    let n = u32::from_le_bytes(raw[5..9].try_into().map_err(|_| 1)?);
    let mut i = 9usize;
    let mut out = Vec::new();
    for _ in 0..n {
        if i.checked_add(26).filter(|e| *e <= raw.len()).is_none() { return Err(1); }
        let hdr = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let size = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let body = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let nl = u16::from_le_bytes(raw[i..i+2].try_into().map_err(|_| 1)?) as usize; i += 2;
        let end = i.checked_add(nl).ok_or(1)?;
        if end > raw.len() { return Err(1); }
        let name = std::str::from_utf8(&raw[i..end]).map_err(|_| 1)?.to_string();
        i = end;
        out.push(Rec { name, hdr, size, body });
    }
    if i != raw.len() { return Err(1); }
    Ok(out)
}

fn load(raw: &[u8], body: u64, size: u64) -> Result<Vec<u8>, i32> {
    let s = usize::try_from(body).map_err(|_| 1)?;
    let n = usize::try_from(size).map_err(|_| 1)?;
    let e = s.checked_add(n).ok_or(1)?;
    if e > raw.len() { return Err(1); }
    Ok(raw[s..e].to_vec())
}

fn digest(text: &str) -> Result<String, i32> {
    use std::io::Write;
    let mut child = std::process::Command::new("python3")
        .args(["-c", "import hashlib,sys; print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())"])
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn().map_err(|_| 1)?;
    child.stdin.as_mut().ok_or(1)?.write_all(text.as_bytes()).map_err(|_| 1)?;
    drop(child.stdin.take());
    let out = child.wait_with_output().map_err(|_| 1)?;
    if !out.status.success() { return Err(1); }
    let s = std::str::from_utf8(&out.stdout).map_err(|_| 1)?.trim().to_string();
    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)) {
        return Err(1);
    }
    Ok(s)
}

