pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let archive = std::fs::read(a).map_err(|_| 1)?;
    let mut recs = read_idx(b)?;
    recs.sort_by_key(|r| r.hdr);

    // Apply the first regular payload for each supported normalized path.
    let mut conf: Option<Vec<u8>> = None;
    let mut logs: Vec<Vec<u8>> = Vec::new();
    let mut seen_log = false;
    let mut names = Vec::new();
    for r in recs {
        let name = alias::fold(&r.name);
        if name == "etc/sys.conf" && conf.is_none() {
            conf = Some(load(&archive, r.body, r.size)?);
            names.push(name);
        } else if name == "var/log/app.log" && !seen_log {
            logs.push(load(&archive, r.body, r.size)?);
            seen_log = true;
            names.push(name);
        }
    }
    let conf = conf.ok_or(1)?;
    if logs.is_empty() { return Err(1); }
    let map = kv::pairs(&conf);
    let t = map.get("timezone").cloned().ok_or(1)?;
    let c = map.get("cluster").cloned().ok_or(1)?;
    let mut e = Vec::new();
    for blob in logs {
        for line in String::from_utf8_lossy(&blob).lines() {
            let value = line.trim();
            if !value.is_empty() { e.push(value.to_string()); }
        }
    }
    e.sort();
    e.dedup();
    let source = std::path::Path::new(a).file_name()
        .and_then(|x| x.to_str()).ok_or(1)?.to_string();
    let w = digest(&names.join("\n"))?;
    Ok(Pack { t, c, e, n: names.len() as u32, s: source, w })
}
